$ErrorActionPreference = 'Stop'
$p=Join-Path $PSScriptRoot 'qwen_fn_audit.csv'
$rows=@(Import-Csv -LiteralPath $p -Encoding UTF8)
$notes=@{
 '6061'=@('A','The article explicitly describes three randomized specimen groups, conflicting with a 1:1 two-arm design; specimens rather than living patients also raise a population question.','randomly assigned to 1 of the following 3 groups','The study should be an RCT with 1:1 parallel twoarm design.')
 '6144'=@('A','This article is itself a systematic review and meta-analysis, not a two-arm RCT; its included studies being RCTs does not change its own design.','Systematic review of the literature, until September 2013, and meta-analysis of randomized controlled trials','The study should be an RCT with 1:1 parallel twoarm design.')
 '6145'=@('A','This article is itself a meta-analysis of several reports, not a two-arm RCT.','six papers were included in meta-analyses','The study should be an RCT with 1:1 parallel twoarm design.')
 '14481'=@('A','The described intervention arms are two drugs and placebo, explicitly not CBT; confirm no additional intervention in the full text.','78 subjects with social phobia received moclobemide (a new reversible inhibitor of monoamine oxidase A) phenelzine, or placebo','Studies were excluded if they did not use CBT')
 '5818'=@('B','Both described arms are conservative treatment; whether this satisfies the broad spine-surgery relevance requirement needs protocol/stage clarification. Surgery eligibility alone is not surgery.','symptoms and clinical findings that would normally qualify them for surgery','The study must be related to spine surgery involving preoperative or intraoperative or postoperative variables.')
 '5847'=@('B','Protocol for a conservative-treatment trial; no reported outcomes is not evidence of nonsignificance, and screening-stage application requires clarification.','study protocol for a randomized controlled trial','Studies that did not report a statistically significant primary or secondary outcome measure.')
 '5849'=@('B','Spine-surgery education RCT reports no significant between-group difference for understanding, but this alone does not establish absence of every qualifying significant primary or secondary outcome.','no statistically significant differences between the groups','Studies that did not report a statistically significant primary or secondary outcome measure.')
 '5852'=@('B','This is a protocol and reports planned outcomes, not trial results; absence of significance results cannot prove a negative result.','protocol for a randomized, blinded, controlled trial','Studies that did not report a statistically significant primary or secondary outcome measure.')
 '5894'=@('B','The study reports living resident participants and cadaver specimens; whether this qualifies as human subjects under the review criterion is ambiguous.','ten novice residents were randomly assigned to two groups','Studies not involving human subjects.')
 '6086'=@('B','This is a spine procedure trial protocol with a parallel design and planned outcomes; it does not establish whether a later reported outcome is significant.','We present the design of a randomized controlled trial','Studies that did not report a statistically significant primary or secondary outcome measure.')
 '14532'=@('B','Combination arms are present, but the trial also contains a CBT-only arm; whether the review excluded the whole study or only combination comparisons is unclear.','cognitive-behavioral therapy (CBT) only (n=77)','used CBT combined with medication or pill placebo')
}
foreach($r in $rows) { if($notes.ContainsKey($r.source_row_index)) { $n=$notes[$r.source_row_index]; if (-not (($r.title + ' ' + $r.abstract).Contains($n[2]))) { throw "Article evidence mismatch $($r.source_row_index)" }; if (-not (($r.inclusion_criteria + ' ' + $r.exclusion_criteria).Contains($n[3]))) { throw "Criteria evidence mismatch $($r.source_row_index)" }; $r.assessment=$n[0];$r.explanation=$n[1];$r.article_evidence=$n[2];$r.criteria_evidence=$n[3] } }
$rows | Export-Csv -LiteralPath $p -NoTypeInformation -Encoding UTF8
$summaries=[Collections.Generic.List[object]]::new()
foreach($review in @('ALL','Leenaars_2019','Muthu_2021','Radjenovic_2013','van_Dis_2020')) { $subset=@($rows | Where-Object { $review -eq 'ALL' -or $_.review_key -eq $review }); foreach($category in @('A','B','C','D','NOT_ASSESSED')) { $n=@($subset | Where-Object assessment -eq $category).Count; $summaries.Add([pscustomobject]@{review_key=$review;assessment=$category;count=$n;denominator=$subset.Count;percentage=[math]::Round(100*$n/$subset.Count,2);note='Partial exploratory manual assessment; NOT_ASSESSED is not category D.'}) } }
$summaries | Export-Csv -LiteralPath (Join-Path $PSScriptRoot 'summary_by_category.csv') -NoTypeInformation -Encoding UTF8
$rows | Group-Object review_key | ForEach-Object { $g=$_.Group; [pscustomobject]@{review_key=$_.Name;fn_count=$_.Count;percent_of_all_fn=[math]::Round(100*$_.Count/$rows.Count,2);missing_abstract=@($g | Where-Object abstract_missing -eq 'True').Count;assessed=@($g | Where-Object assessment -ne 'NOT_ASSESSED').Count;A=@($g | Where-Object assessment -eq 'A').Count;B=@($g | Where-Object assessment -eq 'B').Count;not_assessed=@($g | Where-Object assessment -eq 'NOT_ASSESSED').Count} } | Export-Csv -LiteralPath (Join-Path $PSScriptRoot 'summary_by_review.csv') -NoTypeInformation -Encoding UTF8
Write-Output "Annotated $(@($rows | Where-Object assessment -ne 'NOT_ASSESSED').Count) of $($rows.Count)"
